from typing import List

def min_completion_time(tasks: List[int]) -> int:
    total_sum = sum(tasks)
    n = len(tasks)
    dp = [False] * (total_sum // 2 + 1)
    dp[0] = True
    max_sum = 0

    for task in tasks:
        for j in range(total_sum // 2, task - 1, -1):
            if dp[j - task]:
                dp[j] = True
                max_sum = max(max_sum, j)

    return total_sum - max_sum

def is_anagram_of_palindrome(s: str) -> bool:
    # Normalize the string: convert to lowercase and filter out non-alphabetic characters
    s = ''.join(filter(str.isalpha, s.lower()))

    # Count the frequency of each character
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check if at most one character has an odd count
    odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

    return odd_count <= 1

