def is_balanced_parentheses(s):
    # Initialize a counter for tracking the balance of parentheses
    balance = 0

    # Iterate through each character in the string
    for char in s:
        # If an opening parenthesis is found, increment the balance
        if char == '(':
            balance += 1
        # If a closing parenthesis is found, decrement the balance
        elif char == ')':
            balance -= 1

        # If at any point the balance is negative, return False
        if balance < 0:
            return False

    # If the balance is zero at the end, the parentheses are balanced
    return balance == 0

