def left_rotate_array(arr: list, k: int) -> list:
    if not arr or k == 0:
        return arr
    k %= len(arr)
    return arr[k:] + arr[:k]

def groupBy(l, key):
    ans = {}
    for elem in l:
        if key(elem) in ans:
            ans[key(elem)].append(elem)
        else:
            ans[key(elem)] = [elem]
    return ans


def groupBy2(l, key):
    from collections import defaultdict
    ans = defaultdict(list)
    for elem in l:
        ans[key(elem)].append(elem)
    return dict(ans)

